import {escapeHtml as h} from './community-model.js';
export const runtimeLabel=value=>value===null||value===undefined?'Not measured':Number(value)<.001?'< 0.001 ms':Number(value).toFixed(3)+' ms';
export const memoryLabel=value=>value===null||value===undefined?'Not measured':(Number(value)/1048576).toFixed(2)+' MB';
const benchmarkNote='Practice benchmarks: median of three warmed test-suite passes. Runtime includes the test harness and output; memory is whole-process peak RSS, including the language runtime. Small differences can be noise. Measurements do not determine Big-O complexity.';
export function mountSubmissions(cloud,{notify=()=>{}}={}){
 let generation=0,root=null,problem=null,language='java',sort='runtime',page=0,history=false,owner=null;
 const dialog=document.createElement('dialog');dialog.className='submission-dialog';dialog.setAttribute('aria-labelledby','submissionTitle');document.body.append(dialog);
 function valid(ticket,user){return ticket===generation&&cloud.user?.id===user&&root?.isConnected;}
 async function read(id){const ticket=generation,user=cloud.user?.id;try{const r=await cloud.request('submission-read',{id},user);if(!valid(ticket,user))return;const s=r.submission,a=r.author;dialog.innerHTML='<button class="dialog-close" aria-label="Close solution">×</button><span class="eyebrow">ACCEPTED SOLUTION</span><h2 id="submissionTitle">'+h(a.display_name||a.username||'Your solution')+'</h2><p class="muted">'+h(s.language)+' · '+h(runtimeLabel(s.runtime_ms))+' · '+h(memoryLabel(s.memory_bytes))+'</p><div class="complexity-row"><div><small>Author-stated time</small><b>'+h(s.time_complexity||'Not supplied')+'</b></div><div><small>Author-stated space</small><b>'+h(s.space_complexity||'Not supplied')+'</b></div></div><h3>Approach</h3><p class="submission-approach">'+h(s.approach||'No approach explanation was supplied.')+'</p><h3>Solution</h3><pre class="submission-source"><code>'+h(s.source)+'</code></pre><p class="benchmark-note">'+h(s.suite_kind==='private'?'Private-judge execution time and peak memory for the full suite. Complexity notes are author-stated.':benchmarkNote)+'</p>';dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.showModal();}catch(e){if(valid(ticket,user))notify(e.message);}}
 async function load(){
  const ticket=++generation,user=cloud.user?.id;owner=user;root.innerHTML='<p class="muted">Loading submissions…</p>';if(!user){root.innerHTML='<h3>Learn from accepted solutions</h3><p class="body-copy">Sign in and submit an accepted answer to unlock this problem’s submissions.</p>';return;}
  try{const r=await cloud.request(history?'submission-history':'submission-list',{problemId:problem.id,language,sort,page},user);if(!valid(ticket,user))return;
   let content='<div class="submission-heading"><div><span class="eyebrow">ACCEPTED ANSWERS</span><h3>Different paths. Better ideas.</h3></div><button class="button secondary" data-history>'+ (history?'Rankings':'My submissions')+'</button></div>';
   if(!history&&!r.unlocked){root.innerHTML=content+'<div class="submission-locked"><strong>Solve it to unlock it.</strong><p>Submit an accepted answer for this problem revision to explore shared solutions and their benchmarks.</p></div>';root.querySelector('[data-history]').onclick=()=>{history=true;load();};return;}
   if(!history)content+='<div class="submission-filters"><label>Language<select data-sub-language>'+[['java','Java'],['python','Python 3.11'],['c','C 11'],['cpp','C++ 17']].map(([v,n])=>'<option value="'+v+'" '+(v===language?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Rank by<select data-sub-sort><option value="runtime" '+(sort==='runtime'?'selected':'')+'>Runtime</option><option value="memory" '+(sort==='memory'?'selected':'')+'>Peak memory</option></select></label></div>';
   const rows=r.users||r.items||r.submissions||[];const measurementNote=rows.some(s=>s.suite_kind==='private')?'Private-judge measurements cover the full public and hidden suite. Runtime and peak memory include that judge’s execution overhead; they are not warmed public benchmarks or Big-O.':benchmarkNote;
   content+='<div class="submission-table-wrap"><table class="submission-table"><thead><tr><th>'+(history?'Date':'Rank')+'</th><th>'+(history?'Submission':'Learner')+'</th><th>Runtime</th><th>Memory</th></tr></thead><tbody>'+rows.map(s=>'<tr><td>'+(history?h(new Date(s.created_at).toLocaleDateString()):s.rank<=3?['🥇','🥈','🥉'][s.rank-1]:'#'+Number(s.rank))+'</td><td><button type="button" class="submission-open" data-sub="'+h(s.id)+'">'+(!history?'<span class="chat-avatar">'+(s.avatar_url?'<img alt="" src="'+h(s.avatar_url)+'" referrerpolicy="no-referrer">':h((s.display_name||'?').charAt(0)))+'</span>':'')+'<span><strong>'+h(history?s.language:(s.display_name||s.username))+'</strong><small>'+h(history?(s.shared?'Shared':'Private'):'@'+s.username)+'</small></span></button></td><td>'+h(runtimeLabel(s.runtime_ms))+'</td><td>'+h(memoryLabel(s.memory_bytes))+'</td></tr>').join('')+'</tbody></table></div>';
   if(!rows.length)content+='<p class="muted">'+(history?'No accepted submissions yet.':'No shared benchmarks in this language yet. Yours could be the first.')+'</p>';
   if(!history)content+='<div class="submission-pager"><button data-prev '+(page===0?'disabled':'')+'>← Previous</button><span>Page '+(page+1)+'</span><button data-next '+(rows.length<25?'disabled':'')+'>Next →</button></div>';
   content+='<p class="benchmark-note">'+h(measurementNote)+' Only the current problem revision and each learner’s best shared result appear. Rankings are per language.</p>';root.innerHTML=content;
   root.querySelector('[data-history]').onclick=()=>{history=!history;page=0;load();};root.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>read(b.dataset.sub));root.querySelector('[data-sub-language]')?.addEventListener('change',e=>{language=e.target.value;page=0;load();});root.querySelector('[data-sub-sort]')?.addEventListener('change',e=>{sort=e.target.value;page=0;load();});root.querySelector('[data-prev]')?.addEventListener('click',()=>{page--;load();});root.querySelector('[data-next]')?.addEventListener('click',()=>{page++;load();});
  }catch(e){if(valid(ticket,user))root.textContent=e.message;}
 }
 return{mount(element,p,lang){generation++;root=element;problem=p;language=lang;sort='runtime';page=0;history=false;load();},close(){generation++;root=null;if(dialog.open)dialog.close();},refresh(){if(root?.isConnected&&cloud.user?.id===owner)load();}};
}
export function requestSubmission({problem,language}){
 return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='submission-dialog submit-confirm';dialog.setAttribute('aria-labelledby','submitTitle');dialog.innerHTML='<button class="dialog-close" type="button" aria-label="Cancel submission">×</button><span class="eyebrow">READY TO SUBMIT</span><h2 id="submitTitle">'+h(problem.title)+'</h2><p class="body-copy">Your '+h(language)+' solution will run against the published test suite. An accepted answer unlocks shared submissions.</p><form><label>Explain your approach <small>optional</small><textarea name="approach" rows="3" maxlength="5000" placeholder="What idea makes your solution work?"></textarea></label><div class="submission-complexity"><label>Time complexity<input name="time" maxlength="80" placeholder="e.g. O(n)"></label><label>Extra space complexity<input name="space" maxlength="80" placeholder="e.g. O(n)"></label></div><label class="share-solution"><input name="shared" type="checkbox"><span>Share my accepted solution<small>Other learners who solve this revision can view your code and explanation. Leave unchecked to keep it private.</small></span></label><p class="benchmark-note">Java submissions use JDK 21; browser Run uses Java 17. Runtime and peak memory are practice measurements. Complexity notes are your explanation, not automatically verified.</p><div class="submission-actions"><button type="button" class="button secondary" data-cancel>Cancel</button><button class="button primary" type="submit">Submit solution →</button></div></form>';document.body.append(dialog);let result=null;dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);result={approach:f.get('approach'),timeComplexity:f.get('time'),spaceComplexity:f.get('space'),shared:f.get('shared')==='on',nonce:crypto.randomUUID()};dialog.close();};dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();resolve(result);},{once:true});dialog.showModal();});
}
